//! The compiler checks the parser library states: every source of the table against the byte ranges the pinned Ruff 0.16.5
//! reports as invalid syntax for it at Python 3.10 (`ruff check --isolated --target-version py310`, generated by
//! parity-a/probes/syntax/gen.py; a `.pyi` copy reports the same), each read as a module and as a stub.

use super::fixtures::diagnostics::diagnostics;
use crate::cases::{Case, CaseName, Expect, Word, run};
use crate::outbound::syntax::types::PythonSourceKind;

/// A source and the reference's ranges for it.
type Input = (&'static str, &'static [(u32, u32)]);

/// The reference table: each check, and the guards that bound it.
const CASES: &[Case<Input, (), ()>] = &[
    Case {
        name: CaseName("wildcard_before_another_case"),
        word: Word::Succeeds,
        input: || {
            (
                "match value:\n    case _:\n        pass\n    case 1:\n        pass\n",
                &[(22, 23)],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("capture_before_another_case"),
        word: Word::Succeeds,
        input: || {
            (
                "match value:\n    case irrefutable:\n        pass\n    case 1:\n        pass\n",
                &[(22, 33)],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("capture_alias_before_another_case"),
        word: Word::Succeeds,
        input: || {
            (
                "match value:\n    case first as second:\n        pass\n    case 1:\n        pass\n",
                &[(22, 27)],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("capture_in_or_before_another_case"),
        word: Word::Succeeds,
        input: || {
            (
                "match value:\n    case 1 | other:\n        pass\n    case 2:\n        pass\n",
                &[(22, 31), (26, 31)],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("capture_as_last_case"),
        word: Word::Succeeds,
        input: || {
            (
                "match value:\n    case 1:\n        pass\n    case other:\n        pass\n",
                &[],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("guarded_capture_before_another_case"),
        word: Word::Succeeds,
        input: || {
            (
                "match value:\n    case other if other:\n        pass\n    case 1:\n        pass\n",
                &[],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("duplicate_mapping_key"),
        word: Word::Succeeds,
        input: || {
            (
                "match x:\n    case {'key': 1, 'key': 2}:\n        pass\n",
                &[(29, 34)],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("duplicate_class_attribute"),
        word: Word::Succeeds,
        input: || {
            (
                "match x:\n    case Point(x=1, x=2):\n        pass\n",
                &[(29, 30)],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("name_bound_twice"),
        word: Word::Succeeds,
        input: || ("match x:\n    case [a, a]:\n        pass\n", &[(22, 23)]),
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("name_bound_twice_in_mapping_rest"),
        word: Word::Succeeds,
        input: || {
            (
                "match x:\n    case {'k': a, **a}:\n        pass\n",
                &[(29, 30)],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("starred_return"),
        word: Word::Succeeds,
        input: || ("def func():\n    return *x\n", &[(23, 25)]),
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("starred_for_target"),
        word: Word::Succeeds,
        input: || ("for *x in range(10):\n    pass\n", &[(4, 6)]),
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("starred_yield"),
        word: Word::Succeeds,
        input: || ("def func():\n    yield *x\n", &[(22, 24)]),
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("starred_in_tuple_return"),
        word: Word::Succeeds,
        input: || ("def func():\n    return (*x,)\n", &[]),
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("async_comprehension_in_sync_comprehension"),
        word: Word::Succeeds,
        input: || {
            (
                "async def f(): return [[x async for x in foo(n)] for n in range(3)]\n",
                &[(26, 47)],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("async_comprehension_in_async_comprehension"),
        word: Word::Succeeds,
        input: || {
            (
                "async def test(): return [[x async for x in elements(n)] async for n in range(3)]\n",
                &[],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("async_comprehension_after_sync_comprehension"),
        word: Word::Succeeds,
        input: || {
            (
                "async def f():\n    [_ for n in range(3)]\n    [_ async for n in range(3)]\n",
                &[],
            )
        },
        expect: Expect::Value(()),
    },
    Case {
        name: CaseName("async_comprehension_in_function_in_sync_comprehension"),
        word: Word::Succeeds,
        input: || {
            (
                "async def f():\n    [lambda: [x async for x in y] for n in z]\n",
                &[(31, 47)],
            )
        },
        expect: Expect::Value(()),
    },
];

/// Every diagnostic range of `source`, as a module and as a stub, equals the reference's.
fn subject((source, expected): Input) -> Result<(), ()> {
    for kind in [PythonSourceKind::Python, PythonSourceKind::Stub] {
        let found: Vec<(u32, u32)> = diagnostics(source, kind)
            .into_iter()
            .map(|(_, _, _, start, end)| (start, end))
            .collect();
        assert_eq!(found, expected.to_vec(), "{kind:?}: {source}");
    }
    Ok(())
}

#[test]
fn succeeds() {
    assert!(CASES.len() >= 18, "the table stays whole");
    run(CASES, Word::Succeeds, subject);
}
